16     template<typename T, qualifier Q, bool Aligned>
17     struct compute_dot<qua<T, Q>, T, Aligned>
18     {
19         GLM_FUNC_QUALIFIER GLM_CONSTEXPR static T call(qua<T, Q> const& a, qua<T, Q> const& b)
20         {
21             vec<4, T, Q> tmp(a.w * b.w, a.x * b.x, a.y * b.y, a.z * b.z);
22             return (tmp.x + tmp.y) + (tmp.z + tmp.w);
23         }
24     };
25 
26     template<typename T, qualifier Q, bool Aligned>
27     struct compute_quat_add
28     {
29         GLM_FUNC_QUALIFIER GLM_CONSTEXPR static qua<T, Q> call(qua<T, Q> const& q, qua<T, Q> const& p)
30         {
31             return qua<T, Q>::wxyz(q.w + p.w, q.x + p.x, q.y + p.y, q.z + p.z);
32         }
33     };
34 
35     template<typename T, qualifier Q, bool Aligned>
36     struct compute_quat_sub
37     {
38         GLM_FUNC_QUALIFIER GLM_CONSTEXPR static qua<T, Q> call(qua<T, Q> const& q, qua<T, Q> const& p)
39         {
40             return qua<T, Q>::wxyz(q.w - p.w, q.x - p.x, q.y - p.y, q.z - p.z);
41         }
42     };
43 
44     template<typename T, qualifier Q, bool Aligned>
45     struct compute_quat_mul_scalar
46     {
47         GLM_FUNC_QUALIFIER GLM_CONSTEXPR static qua<T, Q> call(qua<T, Q> const& q, T s)
48         {
49             return qua<T, Q>::wxyz(q.w * s, q.x * s, q.y * s, q.z * s);
50         }
51     };
52 
53     template<typename T, qualifier Q, bool Aligned>
54     struct compute_quat_div_scalar
55     {
56         GLM_FUNC_QUALIFIER GLM_CONSTEXPR static qua<T, Q> call(qua<T, Q> const& q, T s)
57         {
58             return qua<T, Q>::wxyz(q.w / s, q.x / s, q.y / s, q.z / s);
59         }
60     };
61 
62     template<typename T, qualifier Q, bool Aligned>
63     struct compute_quat_mul_vec4
64     {
65         GLM_FUNC_QUALIFIER GLM_CONSTEXPR static vec<4, T, Q> call(qua<T, Q> const& q, vec<4, T, Q> const& v)
66         {
67             return vec<4, T, Q>(q * vec<3, T, Q>(v), v.w);
68         }
69     };
