195     template<typename T, qualifier Q>
196     GLM_FUNC_QUALIFIER qua<T, Q>::qua(vec<3, T, Q> const& u, vec<3, T, Q> const& v)
197     {
198         T norm_u_norm_v = sqrt(dot(u, u) * dot(v, v));
199         T real_part = norm_u_norm_v + dot(u, v);
200         vec<3, T, Q> t;
201 
202         if(real_part < static_cast<T>(1.e-6f) * norm_u_norm_v)
203         {
204             // If u and v are exactly opposite, rotate 180 degrees
205             // around an arbitrary orthogonal axis. Axis normalisation
206             // can happen later, when we normalise the quaternion.
207             real_part = static_cast<T>(0);
208             t = abs(u.x) > abs(u.z) ? vec<3, T, Q>(-u.y, u.x, static_cast<T>(0)) : vec<3, T, Q>(static_cast<T>(0), -u.z, u.y);
209         }
210         else
211         {
212             // Otherwise, build quaternion the standard way.
213             t = cross(u, v);
214         }
215 
216         *this = normalize(qua<T, Q>::wxyz(real_part, t.x, t.y, t.z));
217     }
218 
219     template<typename T, qualifier Q>
220     GLM_FUNC_QUALIFIER GLM_CONSTEXPR qua<T, Q>::qua(vec<3, T, Q> const& eulerAngle)
221     {
222         vec<3, T, Q> c = glm::cos(eulerAngle * T(0.5));
223         vec<3, T, Q> s = glm::sin(eulerAngle * T(0.5));
224 
225         this->w = c.x * c.y * c.z + s.x * s.y * s.z;
226         this->x = s.x * c.y * c.z - c.x * s.y * s.z;
227         this->y = c.x * s.y * c.z + s.x * c.y * s.z;
228         this->z = c.x * c.y * s.z - s.x * s.y * c.z;
229     }
