271     template<typename T, qualifier Q>
272     template<typename U>
273     GLM_FUNC_QUALIFIER GLM_CONSTEXPR qua<T, Q> & qua<T, Q>::operator=(qua<U, Q> const& q)
274     {
275         this->w = static_cast<T>(q.w);
276         this->x = static_cast<T>(q.x);
277         this->y = static_cast<T>(q.y);
278         this->z = static_cast<T>(q.z);
