289     template<typename T, qualifier Q>
290     template<typename U>
291     GLM_FUNC_QUALIFIER GLM_CONSTEXPR qua<T, Q> & qua<T, Q>::operator-=(qua<U, Q> const& q)
292     {
293         return (*this = detail::compute_quat_sub<T, Q, detail::is_aligned<Q>::value>::call(*this, qua<T, Q>(q)));
294     }
295 
296     template<typename T, qualifier Q>
297     template<typename U>
298     GLM_FUNC_QUALIFIER GLM_CONSTEXPR qua<T, Q> & qua<T, Q>::operator*=(qua<U, Q> const& r)
299     {
300         qua<T, Q> const p(*this);
301         qua<T, Q> const q(r);
302 
303         this->w = p.w * q.w - p.x * q.x - p.y * q.y - p.z * q.z;
304         this->x = p.w * q.x + p.x * q.w + p.y * q.z - p.z * q.y;
305         this->y = p.w * q.y + p.y * q.w + p.z * q.x - p.x * q.z;
306         this->z = p.w * q.z + p.z * q.w + p.x * q.y - p.y * q.x;
307         return *this;
308     }
309 
