358     template<typename T, qualifier Q>
359     GLM_FUNC_QUALIFIER GLM_CONSTEXPR vec<3, T, Q> operator*(qua<T, Q> const& q, vec<3, T, Q> const& v)
360     {
361         vec<3, T, Q> const QuatVector(q.x, q.y, q.z);
362         vec<3, T, Q> const uv(glm::cross(QuatVector, v));
363         vec<3, T, Q> const uuv(glm::cross(QuatVector, uv));
364 
365         return v + ((uv * q.w) + uuv) * static_cast<T>(2);
366     }
