406     // -- Boolean operators --
407 
408     template<typename T, qualifier Q>
409     GLM_FUNC_QUALIFIER GLM_CONSTEXPR bool operator==(qua<T, Q> const& q1, qua<T, Q> const& q2)
410     {
411         return q1.x == q2.x && q1.y == q2.y && q1.z == q2.z && q1.w == q2.w;
412     }
413 
414     template<typename T, qualifier Q>
415     GLM_FUNC_QUALIFIER GLM_CONSTEXPR bool operator!=(qua<T, Q> const& q1, qua<T, Q> const& q2)
416     {
417         return q1.x != q2.x || q1.y != q2.y || q1.z != q2.z || q1.w != q2.w;
418     }
